css:
/* From Uiverse.io by ActiveIceDigital - Tags: notification */
@keyframes ud {
  0% {
    transform: translateY(-1px);
    opacity: 0;
  }

  50% {
    transform: translateY(-5px);
    opacity: 1;
  }

  100% {
    transform: translateY(-1px);
    opacity: 0;
  }
}

.__UIV_SCOPE__ .notification {
  width: 250px;
  height: 60px;
  background: rgba(0, 0, 0, 0.5);
  border-radius: 14px;
  padding: 5px 15px;
  text-align: center;
  box-shadow: 2px 2px 0px 1px rgba(255, 0, 0, 0.5) inset, 
  -2px -2px 0px 1px rgba(255, 0, 0, 0.8) inset,
  0px 2px 5px 0px rgba(0, 0, 0, .25);
}

.__UIV_SCOPE__ #lvl {
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-size: 20px;
}

.__UIV_SCOPE__ .notification > span {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.__UIV_SCOPE__ #level {
  display: flex;
  justify-content: center;
  margin-top: 5px;
  gap: 5px;
}

.__UIV_SCOPE__ .one {
  display: inline-block;
  font-size: 25px;
  line-height: 25px;
  animation: ud 1s ease-in-out infinite;
  color: rgba(255, 0, 0, 0.95);
}
